#include <vmlinux.h>
#include <bpf/bpf_helpers.h>

struct sample {
	__u64 value;
};

struct {
	__uint(type, BPF_MAP_TYPE_RINGBUF);
	__uint(max_entries, 4096);
} ringbuf SEC(".maps");

SEC("?raw_tp")
int entry(void *ctx)
{
	struct bpf_dynptr ptr1, ptr2;
	struct sample *sample;

	bpf_ringbuf_reserve_dynptr(&ringbuf, sizeof(*sample), 0, &ptr1);
	bpf_ringbuf_reserve_dynptr(&ringbuf, sizeof(*sample), 0, &ptr2);

	sample = bpf_dynptr_data(&ptr1, 0, sizeof(*sample));
	if (!sample) {
		bpf_ringbuf_discard_dynptr(&ptr1, 0);
		bpf_ringbuf_discard_dynptr(&ptr2, 0);
		return 0;
	}

	bpf_ringbuf_submit_dynptr(&ptr1, 0);
	// Add discard for ptr2 in the non-NULL branch
	bpf_ringbuf_discard_dynptr(&ptr2, 0);

	return 0;
}
```

 This way, in both branches, both dynptrs are either discarded or submitted (ptr1 is submitted, ptr2 is discarded).

 But note: we are submitting one and discarding the other. That is acceptable because they are two separate reservations.

 Alternatively, we could also submit `ptr2` if we had data for it? But the program doesn't use it. So discarding is the right thing.

 Therefore, the above fix should resolve the reference leak.

